CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE users ADD COLUMN IF NOT EXISTS tenant_id UUID REFERENCES organizations(id);
CREATE TABLE IF NOT EXISTS tenant_memberships(tenant_id UUID NOT NULL REFERENCES organizations(id),user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('creator','editor','rights_reviewer','moderator','publisher','auditor','admin')),active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS music_projects(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),idempotency_key TEXT NOT NULL,name TEXT NOT NULL,project_version TEXT NOT NULL,input_digest CHAR(64) NOT NULL,status TEXT NOT NULL CHECK(status IN('draft','ingested','editing','render_review','queued','rendered','content_review','approved','published','exported','failed','rejected','cancelled')),revision INTEGER NOT NULL DEFAULT 1,project JSONB NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),UNIQUE(tenant_id,name,project_version));
CREATE TABLE IF NOT EXISTS music_assets(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT NOT NULL REFERENCES music_projects(id),asset_ref TEXT NOT NULL,kind TEXT NOT NULL,content_digest CHAR(64) NOT NULL,rights JSONB NOT NULL,performer_consent BOOLEAN NOT NULL DEFAULT FALSE,storage_key TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,content_digest));
CREATE TABLE IF NOT EXISTS music_approvals(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT NOT NULL REFERENCES music_projects(id),actor_id INTEGER NOT NULL REFERENCES users(id),approval_type TEXT NOT NULL CHECK(approval_type IN('rights','moderation')),decision TEXT NOT NULL CHECK(decision IN('approve','reject')),attestation_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,project_id,actor_id,approval_type));
CREATE TABLE IF NOT EXISTS music_render_jobs(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT NOT NULL REFERENCES music_projects(id),idempotency_key CHAR(64) NOT NULL,manifest JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','rendered','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),result_digest CHAR(64),storage_key TEXT,last_error TEXT,usage JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS stem_separation_jobs(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT NOT NULL REFERENCES music_projects(id),request_digest CHAR(64) NOT NULL,request JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','processing','completed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),outputs JSONB,last_error TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,request_digest));
CREATE TABLE IF NOT EXISTS music_publications(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT NOT NULL REFERENCES music_projects(id),channel TEXT NOT NULL,export_digest CHAR(64) NOT NULL,watermark_digest CHAR(64) NOT NULL,disclosure TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','published','reconciled','dead_letter')),external_id TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS music_acceptance_evaluations(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT REFERENCES music_projects(id),fixture_version TEXT NOT NULL,metrics JSONB NOT NULL,evidence_digest CHAR(64) NOT NULL,evaluated_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS music_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT NOT NULL REFERENCES music_projects(id),actor_id INTEGER REFERENCES users(id),event_type TEXT NOT NULL,from_status TEXT,to_status TEXT,payload JSONB NOT NULL DEFAULT '{}'::jsonb,evidence_digest CHAR(64),occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION prevent_music_event_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'music provenance is append-only'; END; $$ LANGUAGE plpgsql;DROP TRIGGER IF EXISTS music_events_append_only ON music_events;CREATE TRIGGER music_events_append_only BEFORE UPDATE OR DELETE ON music_events FOR EACH ROW EXECUTE FUNCTION prevent_music_event_mutation();
CREATE TABLE IF NOT EXISTS music_integration_failures(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),project_id BIGINT,provider TEXT NOT NULL,operation TEXT NOT NULL,retryable BOOLEAN NOT NULL,error_code TEXT NOT NULL,sanitized_detail TEXT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
